mapper.select:
SELECT COUNT(*) FROM fault_experiment
WHERE managed_system_id = #{systemId}
  AND status IN ('INJECTING', 'ACTIVE', 'RESETTING')

  AND id <> #{exceptId}

FOR SHARE

mapper.update:
UPDATE fault_experiment
SET status = 'FAILED', error_message = #{message}, updated_at = #{now}
WHERE id = #{id} AND status = #{from}

UPDATE fault_experiment
SET status = 'RESETTING', updated_at = #{now}
WHERE id = #{id} AND status = #{from}

UPDATE fault_experiment
SET status = 'RESET', reset_at = #{resetAt}, updated_at = #{resetAt}
WHERE id = #{id} AND status = 'RESETTING'

UPDATE fault_experiment
SET status = 'FAILED', error_message = #{message}, updated_at = #{now}
WHERE status IN ('INJECTING', 'RESETTING') AND updated_at < #{startedBefore}
